30	type ActionResult<T = void> =
31	  | { ok: true; data: T }
32	  | { ok: false; error: string }
33	
34	type MutationRole = 'owner' | 'admin' | 'artist'
35	type ReadRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'
36	
37	function canWrite(role: ReadRole): role is MutationRole {
38	  return role === 'owner' || role === 'admin' || role === 'artist'
39	}
40	
41	function canAdmin(role: ReadRole): boolean {
42	  return role === 'owner' || role === 'admin'
43	}
