45	// ─── Create ────────────────────────────────────────────────────────────────────
46	
47	export async function createProjectAction(
48	  formData: FormData
49	): Promise<ActionResult<{ id: string }>> {
50	  const auth = await getAuthenticatedUser()
51	  if (!auth) return { ok: false, error: 'Not authenticated' }
52	
53	  const role = auth.role as ReadRole
54	  // Receptionist can create projects per RLS
55	  if (role === 'guest_artist') return { ok: false, error: 'Insufficient permissions' }
56	
57	  // secondaryArtistIds sent as repeated entries: secondaryArtistIds[]
58	  const secondaryArtistRaw = formData.getAll('secondaryArtistIds[]')
59	  const secondaryArtistIds = secondaryArtistRaw
60	    .filter((v): v is string => typeof v === 'string' && v.length > 0)
61	
62	  // pendingReferenceUrls sent as repeated entries: pendingReferenceUrls[]
63	  const pendingReferenceUrlsRaw = formData.getAll('pendingReferenceUrls[]')
64	  const pendingReferenceUrls = pendingReferenceUrlsRaw
65	    .filter((v): v is string => typeof v === 'string' && v.length > 0)
66	
67	  const raw = {
68	    clientId: formData.get('clientId'),
69	    name: formData.get('name'),
70	    description: formData.get('description') || undefined,
71	    placement: formData.get('placement') || undefined,
72	    style: formData.get('style') || undefined,
73	    primaryArtistId: formData.get('primaryArtistId') || undefined,
74	    secondaryArtistIds: secondaryArtistIds.length > 0 ? secondaryArtistIds : undefined,
75	    totalSessionsPlanned: formData.get('totalSessionsPlanned')
76	      ? Number(formData.get('totalSessionsPlanned'))
77	      : undefined,
78	    totalPriceCents: formData.get('totalPriceCents')
79	      ? Number(formData.get('totalPriceCents'))
80	      : 0,
81	    moodboardUrl: formData.get('moodboardUrl') || undefined,
82	    initialDepositCents: formData.get('initialDepositCents')
83	      ? Number(formData.get('initialDepositCents'))
84	      : undefined,
85	    size: formData.get('size') || undefined,
86	    colorMode: formData.get('colorMode') || undefined,
87	    depositApplyRule: formData.get('depositApplyRule') || undefined,
88	    referenceNotes: formData.get('referenceNotes') || undefined,
89	    requestDeposit: formData.get('requestDeposit') === 'true' ? true : undefined,
90	    pendingReferenceUrls: pendingReferenceUrls.length > 0 ? pendingReferenceUrls : undefined,
91	  }
92	
93	  const parsed = projectCreateSchema.safeParse(raw)
94	  if (!parsed.success) {
95	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
96	  }
97	
98	  try {
99	    const project = await createProject(auth.studioId, parsed.data)
100	    revalidatePath('/projects')
101	    return { ok: true, data: { id: project.id } }
102	  } catch (err) {
103	    logger.error({ err }, 'createProjectAction failed')
104	    return { ok: false, error: 'Failed to create project' }
105	  }
106	}
