109	
110	export async function updateProjectAction(
111	  id: string,
112	  formData: FormData
113	): Promise<ActionResult<void>> {
114	  const auth = await getAuthenticatedUser()
115	  if (!auth) return { ok: false, error: 'Not authenticated' }
116	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
117	
118	  const raw = {
119	    name: formData.get('name') || undefined,
120	    description: formData.get('description') ?? undefined,
121	    placement: formData.get('placement') ?? undefined,
122	    style: formData.get('style') ?? undefined,
123	    primaryArtistId: formData.get('primaryArtistId') ?? undefined,
124	    totalSessionsPlanned: formData.get('totalSessionsPlanned')
125	      ? Number(formData.get('totalSessionsPlanned'))
126	      : undefined,
127	    totalPriceCents: formData.get('totalPriceCents')
128	      ? Number(formData.get('totalPriceCents'))
129	      : undefined,
130	    moodboardUrl: formData.get('moodboardUrl') ?? undefined,
131	    status: formData.get('status') ?? undefined,
132	  }
133	
134	  const parsed = projectUpdateSchema.safeParse(raw)
135	  if (!parsed.success) {
136	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
137	  }
138	
139	  try {
140	    await updateProject(auth.studioId, id, parsed.data)
141	    revalidatePath('/projects')
142	    revalidatePath(`/projects/${id}`)
143	    return { ok: true, data: undefined }
144	  } catch (err) {
145	    logger.error({ err, id }, 'updateProjectAction failed')
146	    return { ok: false, error: 'Failed to update project' }
147	  }
148	}
