170	export async function updateProjectStatusAction(
171	  id: string,
172	  status: ProjectStatus
173	): Promise<ActionResult<void>> {
174	  const auth = await getAuthenticatedUser()
175	  if (!auth) return { ok: false, error: 'Not authenticated' }
176	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
177	
178	  const supabase = await createClient()
179	
180	  // Fetch old status for activity log
181	  const { data: existing } = await supabase
182	    .from('projects')
183	    .select('status')
184	    .eq('id', id)
185	    .eq('studio_id', auth.studioId)
186	    .single()
187	
188	  const { error } = await supabase
189	    .from('projects')
190	    .update({ status, updated_at: new Date().toISOString() })
191	    .eq('id', id)
192	    .eq('studio_id', auth.studioId)
193	
194	  if (error) {
195	    logger.error({ error, id, status }, 'updateProjectStatusAction failed')
196	    return { ok: false, error: 'Failed to update status' }
197	  }
198	
199	  // Write activity log — best-effort (non-fatal)
200	  // TODO: insert into project_activity_log once table + types land (Dato migration pending)
201	  void existing // old status consumed once project_activity_log table is added
202	
203	  revalidatePath('/projects')
204	  revalidatePath(`/projects/${id}`)
205	  return { ok: true, data: undefined }
206	}
