/**
 * Returns pre-fill data for the booking drawer when offering a slot
 * to a waitlist entry. This action does not create a booking.

input.new_string:
/**
 * Send a Google review request SMS (fallback to email) for a completed booking.
 *
 * Copy:
 *   SMS: "Hey {first_name}! Hope you're loving your tattoo from {artist} at {studio}. If you have 60s, a review would mean the world: {review_link}"
 *   Email: same message but via Resend when no phone is on file.
 *
 * review_link = studios.google_review_url if the column exists and is populated,
 * otherwise falls back to the studio's public booking page.
 * NOTE: studios.google_review_url is not yet in the DB schema — the fallback is used
 * until Dato adds that column and `pnpm db:types` is rerun.
 */
export async function sendReviewRequestAction(
  bookingId: string,
): Promise<ActionResult> {
  const { studioId, studio } = await getActiveStudio()
  const supabase = await createClient()

  // Fetch booking + client + artist, scoped to this studio (implicit membership guard)
  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .select(`
      id,
      clients!inner(first_name, phone, email),
      artists!inner(display_name)
    `)
    .eq('id', bookingId)
    .eq('studio_id', studioId)
    .single()

  if (bookingErr || !booking) {
    return { ok: false, error: 'Booking not found or access denied' }
  }

  const client = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
  const artist = Array.isArray(booking.artists) ? booking.artists[0] : booking.artists

  if (!client) {
    return { ok: false, error: 'Client data missing' }
  }

  const firstName = client.first_name ?? 'there'
  const artistName = artist?.display_name ?? studio.name
  const studioName = studio.name

  // google_review_url not yet in schema — fall back to public booking page
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
  const reviewLink = `${appUrl}/book/${studio.slug}`

  const messageBody =
    `Hey ${firstName}! Hope you're loving your tattoo from ${artistName} at ${studioName}. ` +
    `If you have 60s, a review would mean the world: ${reviewLink}`

  const phone = client.phone

  if (phone) {
    try {
      const { sendSms } = await import('@/lib/sms/twilio')
      await sendSms({ to: phone, body: messageBody })
    } catch (err) {
      if (err instanceof Error && err.constructor.name === 'TwilioNotConfiguredError') {
        logger.warn({ bookingId }, 'inbox: Twilio not configured — review SMS skipped, attempting email')
      } else {
        logger.error({ err, bookingId }, 'inbox: review request SMS failed — attempting email fallback')
        // Fall through to email fallback below
      }
      // Email fallback
      const email = client.email
      if (!email) {
        return { ok: false, error: "Couldn't send reminder. Try again or contact support." }
      }
      try {
        const { sendEmail } = await import('@/lib/email/resend')
        await sendEmail({
          to: email,
          template: 'booking_confirmation',
          data: {
            studioName,
            clientFirstName: firstName,
            serviceName: 'your recent session',
            artistName,
            scheduledAt: new Date().toISOString(),
            endAt: new Date().toISOString(),
            durationMin: 0,
            priceCents: 0,
            depositCents: 0,
            depositPaid: true,
            bookingReference: bookingId,
            depositPaymentUrl: reviewLink,
          },
        })
      } catch (emailErr) {
        logger.error({ emailErr, bookingId }, 'inbox: review request email fallback also failed')
        return { ok: false, error: "Couldn't send reminder. Try again or contact support." }
      }
    }
  } else {
    // No phone — send email directly
    const email = client.email
    if (!email) {
      return { ok: false, error: 'Client has no phone or email on file' }
    }
    try {
      const { sendEmail } = await import('@/lib/email/resend')
      await sendEmail({
        to: email,
        template: 'booking_confirmation',
        data: {
          studioName,
          clientFirstName: firstName,
          serviceName: 'your recent session',
          artistName,
          scheduledAt: new Date().toISOString(),
          endAt: new Date().toISOString(),
          durationMin: 0,
          priceCents: 0,
          depositCents: 0,
          depositPaid: true,
          bookingReference: bookingId,
          depositPaymentUrl: reviewLink,
        },
      })
    } catch (emailErr) {
      logger.error({ emailErr, bookingId }, 'inbox: review request email failed')
      return { ok: false, error: "Couldn't send reminder. Try again or contact support." }
    }
  }

  return upsertAssignment(studioId, 'review-request', bookingId, {
    resolved_at: new Date().toISOString(),
    note: 'Review request sent',
  })
}

/**
 * Send a birthday offer SMS (fallback to email) to a client.
 *
 * Default copy:
 *   "Happy birthday {first_name}! 🎂 Treat yourself — we've got an opening this week. Book here: {booking_link}"
 *
 * Pass customMessage to override the body entirely.
 * booking_link = NEXT_PUBLIC_APP_URL + /book/{studio.slug}
 */
export async function sendBirthdayOfferAction(
  clientId: string,
  customMessage?: string,
): Promise<ActionResult> {
  const { studioId, studio } = await getActiveStudio()
  const supabase = await createClient()

  const { data: client, error: clientErr } = await supabase
    .from('clients')
    .select('id, first_name, phone, email')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (clientErr || !client) {
    return { ok: false, error: 'Client not found or access denied' }
  }

  const firstName = client.first_name ?? 'there'
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
  const bookingLink = `${appUrl}/book/${studio.slug}`

  const messageBody =
    customMessage ??
    `Happy birthday ${firstName}! \uD83C\uDF82 Treat yourself — we've got an opening this week. Book here: ${bookingLink}`

  const phone = client.phone

  if (phone) {
    try {
      const { sendSms } = await import('@/lib/sms/twilio')
      await sendSms({ to: phone, body: messageBody })
    } catch (err) {
      if (err instanceof Error && err.constructor.name === 'TwilioNotConfiguredError') {
        logger.warn({ clientId }, 'inbox: Twilio not configured — birthday SMS skipped, attempting email')
      } else {
        logger.error({ err, clientId }, 'inbox: birthday SMS failed — attempting email fallback')
      }
      // Email fallback
      const email = client.email
      if (!email) {
        return { ok: false, error: "Couldn't send reminder. Try again or contact support." }
      }
      try {
        const { sendEmail } = await import('@/lib/email/resend')
        await sendEmail({
          to: email,
          template: 'booking_confirmation',
          data: {
            studioName: studio.name,
            clientFirstName: firstName,
            serviceName: 'Book your next session',
            artistName: studio.name,
            scheduledAt: new Date().toISOString(),
            endAt: new Date().toISOString(),
            durationMin: 0,
            priceCents: 0,
            depositCents: 0,
            depositPaid: true,
            bookingReference: clientId,
            depositPaymentUrl: bookingLink,
          },
        })
      } catch (emailErr) {
        logger.error({ emailErr, clientId }, 'inbox: birthday email fallback also failed')
        return { ok: false, error: "Couldn't send reminder. Try again or contact support." }
      }
    }
  } else {
    const email = client.email
    if (!email) {
      return { ok: false, error: 'Client has no phone or email on file' }
    }
    try {
      const { sendEmail } = await import('@/lib/email/resend')
      await sendEmail({
        to: email,
        template: 'booking_confirmation',
        data: {
          studioName: studio.name,
          clientFirstName: firstName,
          serviceName: 'Book your next session',
          artistName: studio.name,
          scheduledAt: new Date().toISOString(),
          endAt: new Date().toISOString(),
          durationMin: 0,
          priceCents: 0,
          depositCents: 0,
          depositPaid: true,
          bookingReference: clientId,
          depositPaymentUrl: bookingLink,
        },
      })
    } catch (emailErr) {
      logger.error({ emailErr, clientId }, 'inbox: birthday email failed')
      return { ok: false, error: "Couldn't send reminder. Try again or contact support." }
    }
  }

  return upsertAssignment(studioId, 'client-birthday', clientId, {
    resolved_at: new Date().toISOString(),
    note: 'Birthday offer sent',
  })
}

