// ─── Review request & birthday — extended kinds not yet in InboxItemKind ─────
//
// These two kinds ('review-request', 'client-birthday') are not yet in the
// generated InboxItemKind union (pending Dato migration + pnpm db:types).
// We write directly to inbox_assignments with a string literal to avoid
// touching the generated types file. When db:types is regenerated with the
// new enum values, this comment and cast can be removed.

/**
 * Send a Google review request SMS to the client of a completed booking.
 * Falls back to email if no phone is on file.
 *
 * SMS: "Hey {first_name}! Hope you're loving your tattoo from {artist} at {studio}.
 *       If you have 60s, a review would mean the world: {review_link}"
 *
 * review_link = studios.google_review_url (TODO: add column via Dato migration).
 * Until then, falls back to the studio's public booking page (/book/{slug}).
 */
export async function sendReviewRequestAction(
  bookingId: string,
): Promise<ActionResult> {
  const { studioId, studio } = await getActiveStudio()
  const supabase = await createClient()

  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .select(`
      id,
      clients!inner(first_name, phone, email),
      artists!inner(display_name)
    `)
    .eq('id', bookingId)
    .eq('studio_id', studioId)
    .single()

  if (bookingErr || !booking) {
    return { ok: false, error: 'Booking not found or access denied' }
  }

  const client = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
  const artist = Array.isArray(booking.artists) ? booking.artists[0] : booking.artists

  if (!client) {
    return { ok: false, error: 'Client data missing' }
  }

  const firstName = client.first_name ?? 'there'
  const artistName = artist?.display_name ?? studio.name
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
  // TODO: use studios.google_review_url once Dato adds the column
  const reviewLink = `${appUrl}/book/${studio.slug}`

  const body =
    `Hey ${firstName}! Hope you're loving your tattoo from ${artistName} at ${studio.name}. ` +
    `If you have 60s, a review would mean the world: ${reviewLink}`

  const phone = client.phone
  let sent = false

  if (phone) {
    try {
      const { sendSms } = await import('@/lib/sms/twilio')
      await sendSms({ to: phone, body })
      sent = true
    } catch (err) {
      if (err instanceof Error && err.constructor.name === 'TwilioNotConfiguredError') {
        logger.warn({ bookingId }, 'inbox/review-request: Twilio not configured — falling back to email')
      } else {
        logger.error({ err, bookingId }, 'inbox/review-request: SMS failed — falling back to email')
      }
    }
  }

  if (!sent) {
    const email = client.email
    if (!email) {
      return { ok: false, error: 'Client has no phone or email on file' }
    }
    try {
      const { sendEmail } = await import('@/lib/email/resend')
      await sendEmail({
        to: email,
        template: 'booking_confirmation',
        data: {
          studioName: studio.name,
          clientFirstName: firstName,
          serviceName: 'your recent session',
          artistName,
          scheduledAt: new Date().toISOString(),
          endAt: new Date().toISOString(),
          durationMin: 0,
          priceCents: 0,
          depositCents: 0,
          depositPaid: true,
          bookingReference: bookingId,
          depositPaymentUrl: reviewLink,
        },
      })
    } catch (emailErr) {
      logger.error({ emailErr, bookingId }, 'inbox/review-request: email also failed')
      return { ok: false, error: "Couldn't send reminder. Try again or contact support." }
    }
  }

  // Resolve the inbox_assignments row — 'review-request' not yet in InboxItemKind union
  const { error: upsertErr } = await supabase
    .from('inbox_assignments')
    .upsert(
      {
        studio_id: studioId,
        item_kind: 'review-request' as 'deposit', // cast to satisfy TS until db:types regenerated
        item_id: bookingId,
        resolved_at: new Date().toISOString(),
        note: 'Review request sent',
        updated_at: new Date().toISOString(),
      },
      { onConflict: 'studio_id,item_kind,item_id' },
    )

  if (upsertErr) {
    logger.warn({ error: upsertErr.message, bookingId }, 'inbox/review-request: assignment upsert failed (non-fatal)')
  }

  revalidatePath('/inbox')
  return { ok: true }
}

/**
 * Send a birthday offer SMS (fallback email) to a client.
 *
 * Default: "Happy birthday {first_name}! 🎂 Treat yourself — we've got an opening
 *           this week. Book here: {booking_link}"
 *
 * Pass customMessage to override the body entirely.
 * booking_link = NEXT_PUBLIC_APP_URL + /book/{studio.slug}
 */
export async function sendBirthdayOfferAction(
  clientId: string,
  customMessage?: string,
): Promise<ActionResult> {
  const { studioId, studio } = await getActiveStudio()
  const supabase = await createClient()

  const { data: client, error: clientErr } = await supabase
    .from('clients')
    .select('id, first_name, phone, email')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (clientErr || !client) {
    return { ok: false, error: 'Client not found or access denied' }
  }

  const firstName = client.first_name ?? 'there'
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
  const bookingLink = `${appUrl}/book/${studio.slug}`

  const body =
    customMessage ??
    `Happy birthday ${firstName}! \uD83C\uDF82 Treat yourself \u2014 we\u2019ve got an opening this week. Book here: ${bookingLink}`

  const phone = client.phone
  let sent = false

  if (phone) {
    try {
      const { sendSms } = await import('@/lib/sms/twilio')
      await sendSms({ to: phone, body })
      sent = true
    } catch (err) {
      if (err instanceof Error && err.constructor.name === 'TwilioNotConfiguredError') {
        logger.warn({ clientId }, 'inbox/birthday: Twilio not configured — falling back to email')
      } else {
        logger.error({ err, clientId }, 'inbox/birthday: SMS failed — falling back to email')
      }
    }
  }

  if (!sent) {
    const email = client.email
    if (!email) {
      return { ok: false, error: 'Client has no phone or email on file' }
    }
    try {
      const { sendEmail } = await import('@/lib/email/resend')
      await sendEmail({
        to: email,
        template: 'booking_confirmation',
        data: {
          studioName: studio.name,
          clientFirstName: firstName,
          serviceName: 'Book your next session',
          artistName: studio.name,
          scheduledAt: new Date().toISOString(),
          endAt: new Date().toISOString(),
          durationMin: 0,
          priceCents: 0,
          depositCents: 0,
          depositPaid: true,
          bookingReference: clientId,
          depositPaymentUrl: bookingLink,
        },
      })
